INSERT INTO `doctoradvice` VALUES (3,'2026-08-24 12:37:20',18,'情绪低落','你的描述可能涉及心身相关因素，建议关注并进一步排查。','精神心理科 / 临床心理科','建议先到上述科室就诊，排除器质性问题后再考虑心理因素。参考：持续2周以上建议专业评估','keyword'),(4,'2026-08-24 12:59:47',18,'最近总是失眠、头痛，白天没精神','你的描述可能涉及心身相关因素，建议关注并进一步排查。','睡眠门诊 / 神经内科 / 精神心理科；神经内科 → 精神心理科','建议先到上述科室就诊，排除器质性问题后再考虑心理因素。','keyword'),(5,'2026-08-24 12:59:47',18,'最近总是胸闷、心慌，有时候喘不上气','你的描述可能涉及心身相关因素，建议关注并进一步排查。','心内科 → 精神心理科','建议先到上述科室就诊，排除器质性问题后再考虑心理因素。','keyword');
