CREATE TABLE `jiankangyujing` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `yonghuzhanghao` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户账号',
  `yonghuxingming` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户姓名',
  `yujingtixing` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预警提醒',
  `xinlijianyi` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '心理建议',
  `yujingshijian` datetime DEFAULT NULL COMMENT '预警时间',
  `rijiid` bigint DEFAULT NULL COMMENT '触发预警的心情日记id',
  `chulizhuangtai` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fuzeyishenggonghao` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fuzeyishengxingming` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chuliyijian` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_jiankangyujing_yonghuzhanghao` (`yonghuzhanghao`) USING BTREE,
  KEY `idx_jiankangyujing_rijiid` (`rijiid`) USING BTREE,
  CONSTRAINT `fk_jiankangyujing_diary` FOREIGN KEY (`rijiid`) REFERENCES `xinqingriji` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_jiankangyujing_student` FOREIGN KEY (`yonghuzhanghao`) REFERENCES `yonghu` (`yonghuzhanghao`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='健康预警';
