INSERT INTO `xinlizhishi` VALUES (1,'2026-03-05 23:41:18','抑郁情绪','upload/xinlizhishi_抑郁情绪1.jpg,upload/xinlizhishi_抑郁情绪2.jpg,upload/xinlizhishi_抑郁情绪3.jpg','情绪心理','读懂抑郁情绪并自我关怀','','不同于抑郁症是短期负面情绪堆积若持续两周以上需及时寻求帮助表现为提不起劲自我封闭等','D000101','王静','2024-09-02 15:47:31',2,1,'2026-05-11 11:47:43',7,0,2,NULL,NULL,NULL),(2,'2026-03-05 23:41:18','就业焦虑','upload/xinlizhishi_就业焦虑1.jpg,upload/xinlizhishi_就业焦虑2.jpg,upload/xinlizhishi_就业焦虑3.jpg','情绪心理','缓解就业焦虑规划职业方向','','临近毕业因就业市场竞争激烈自我定位模糊引发的焦虑需通过提升能力明确规划缓解','D000102','李娜与','2025-08-10 13:21:09',3,2,'2026-03-06 15:41:18',4,1,2,NULL,NULL,NULL),(3,'2026-03-05 23:41:18','嫉妒心理','upload/xinlizhishi_嫉妒心理1.jpg,upload/xinlizhishi_嫉妒心理2.jpg,upload/xinlizhishi_嫉妒心理3.jpg','情绪心理','正视嫉妒心理转化成长动力','','因他人在学业社交等方面的成就产生不平衡心理需正确疏导转化为自我提升的动力','D000103','孙俪','2025-08-23 13:41:26',3,3,'2026-03-06 15:41:18',3,0,3,NULL,NULL,NULL),(4,'2026-03-05 23:41:18','完美主义','upload/xinlizhishi_完美主义1.jpg,upload/xinlizhishi_完美主义2.jpg,upload/xinlizhishi_完美主义3.jpg','认知心理','接纳不完美活出真实自我','','过度追求完美易导致焦虑拖延害怕尝试需调整认知允许自己有瑕疵','D000104','刘芳','2025-07-25 07:38:56',4,4,'2026-03-06 15:41:18',4,0,4,NULL,NULL,NULL),(5,'2026-03-05 23:41:18','自我认同困惑','upload/xinlizhishi_自我认同困惑1.jpg,upload/xinlizhishi_自我认同困惑2.jpg,upload/xinlizhishi_自我认同困惑3.jpg','认知心理','建立稳定的自我认同','','大学生处于自我认知完善期易因比较产生自我怀疑需通过接纳优缺点明确自身价值','D000105','王磊','2024-05-29 11:32:57',5,5,'2026-03-06 15:41:18',5,0,5,NULL,NULL,NULL),(6,'2026-03-05 23:41:18','孤独感','upload/xinlizhishi_孤独感1.jpg,upload/xinlizhishi_孤独感2.jpg,upload/xinlizhishi_孤独感3.jpg','情绪心理','与孤独和解享受独处时光','','大学生独立意识增强但社交联结不足易产生孤独感需学会自我陪伴建立深层关系','D000106','王明','2023-06-19 18:42:17',6,6,'2026-05-01 17:02:32',7,0,6,NULL,NULL,NULL),(7,'2026-03-05 23:41:18','情感困扰','upload/xinlizhishi_情感困扰1.jpg,upload/xinlizhishi_情感困扰2.jpg,upload/xinlizhishi_情感困扰3.jpg','恋爱心理','理性看待大学生恋爱关系','','恋爱中因需求不匹配沟通不畅或情感挫折引发的心理波动需树立正确恋爱观','D000107','赵刚','2024-04-22 14:08:39',7,7,'2026-03-06 15:41:18',7,0,7,NULL,NULL,NULL),(8,'2026-03-05 23:41:18','社交恐惧','upload/xinlizhishi_社交恐惧1.jpg,upload/xinlizhishi_社交恐惧2.jpg,upload/xinlizhishi_社交恐惧3.jpg','人际心理','打破社交恐惧的枷锁','','对社交场景产生过度担忧恐惧担心被评价拒绝影响正常人际交往多源于自卑或过往负面经历','D000108','李娜','2025-08-30 18:07:51',8,8,'2026-08-21 00:16:06',9,0,8,NULL,NULL,NULL);
